import { useId } from 'react'
import { ICheckboxProps } from '@/src/interfaces/props'
import { useFormContext } from 'react-hook-form'
import ErrorMessage from '../ErrorMessage/ErrorMessage'

export default function Checkbox({ label }: ICheckboxProps) {
    const {
        register,
        formState: { errors }
    } = useFormContext()

    const id = useId()

    return (
        <div className='relative flex gap-2 mb-8 items-center hover:border-[#6C7275]'>
            <input
                className="
                peer 
                relative 
                appearance-none 
                w-6 
                h-6 
                rounded-sm 
                border-2 
                focus:outline-none 
                checked:bg-[#141718] 
                hover:ring 
                hover:ring-[#6C7275]

                after:content-['']
                after:bg-size-[40px] 
                after:bg-center 
                after:bg-no-repeat 
                after:absolute
                after:left-0 
                after:top-0 
                after:h-full
                after:w-full 
                after:bg-[url('data:image/svg+xml;base64,')]
                "
                id={id}
                type='checkbox'
                {...register('policy')}
            />
            <label
                className='font-(family-name:--font-second-inter) font-normal leading-6.5 text-4 text-[#6C7275] cursor-pointer'
                htmlFor={id}
            >
                {label}
            </label>
            <ErrorMessage errors={errors} fieldName='policy' />
        </div>
    )
}

